"""Build final evaluation summaries and browsable galleries from saved selected-model results."""
from pathlib import Path
import argparse,json,html,shutil
import numpy as np,pandas as pd
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt


def main(argv=None):
 p=argparse.ArgumentParser(description=__doc__);p.add_argument('--package-root',type=Path,default=Path(__file__).resolve().parent.parent);a=p.parse_args(argv);root=a.package_root;data=root/'data/nba_passing_output';base=data/'all_season_hub_redistribution';pred=root/'prediction_model';dest=root/'prediction_comparisons';dest.mkdir(exist_ok=True);meta=pd.read_csv(base/'all_team_season_entropy_and_ec.csv');d=pd.read_csv(pred/'team_season_comparison.csv');d=d.merge(meta[['season','team','hub_id','first20_hub_present_games','later_hub_absent_games','primary_eligible','edge_distance_predicted_actual','entropy_predicted','entropy_actual']],on=['season','team'],suffixes=('','_source'),validate='one_to_one');assert len(d)==180 and d.eligible.sum()==100;d['edge_minutes_only']=d.edge_distance_predicted_actual;d['entropy_error_minutes_only']=(d.entropy_predicted-d.entropy_actual).abs();d.to_csv(dest/'all_team_prediction_errors.csv',index=False);d[d.eligible].to_csv(dest/'ten_plus_absence_prediction_errors.csv',index=False)
 models=['minutes_only','current','learned','deletion'];labels={'minutes_only':'Older minutes-only','current':'Initial separate-role','learned':'Final previous-season-only','deletion':'Simple deletion'};summaries=[]
 for sample,q in [('ten_plus_all',d[d.eligible]),('common_with_history',d[d.eligible&d.has_history]),('latest_ten_plus',d[d.eligible&d.season.eq(d.season.max())])]:
  for model in models:
   e=q['edge_'+model];h=q['entropy_error_'+model];delta=e-q.edge_current;summaries.append(dict(sample=sample,model=labels[model],n=len(q),mean_connection_error=e.mean(),median_connection_error=e.median(),mean_entropy_error=h.mean(),median_entropy_error=h.median(),connection_improved_vs_initial=int((delta<-1e-8).sum()),connection_worsened_vs_initial=int((delta>1e-8).sum()),connection_unchanged_vs_initial=int((delta.abs()<=1e-8).sum())))
 summary=pd.DataFrame(summaries);summary.to_csv(dest/'model_comparison.csv',index=False);d[d.eligible].groupby('season').agg(qualifying_team_seasons=('team','size'),with_historical_training=('has_history','sum'),mean_initial_error=('edge_current','mean'),mean_final_error=('edge_learned','mean')).to_csv(dest/'season_summary.csv')
 q=d[d.eligible&d.has_history];fig,axes=plt.subplots(1,2,figsize=(14,6))
 for ax,metric,title in [(axes[0],'edge','Connection error'),(axes[1],'entropy_error','Absolute normalized entropy error')]:
  for latest,color,label in [(False,'#899ca8','Earlier target seasons'),(True,'#197c68',d.season.max())]:
   g=q[q.season.eq(d.season.max())==latest];ax.scatter(g[metric+'_current'],g[metric+'_learned'],c=color,label=label,alpha=.8)
  limit=max(q[metric+'_current'].max(),q[metric+'_learned'].max())*1.06;ax.plot([0,limit],[0,limit],color='firebrick',label='Equal error');ax.set(xlim=(0,limit),ylim=(0,limit),xlabel='Initial separate-role model',ylabel='Final previous-season-only model',title=title);ax.legend(fontsize=8)
 fig.suptitle('Same 85 team-seasons with historical training and 10+ later absences | below diagonal = improved');fig.tight_layout(rect=[0,0,1,.94]);fig.savefig(dest/'initial_vs_final_errors.png',dpi=155);plt.close(fig)
 fig,axes=plt.subplots(1,2,figsize=(14,6));g=summary[summary['sample'].eq('common_with_history')]
 for ax,metric,title in [(axes[0],'mean_connection_error','Mean connection error'),(axes[1],'median_entropy_error','Median absolute entropy error')]:
  ax.bar(np.arange(len(g)),g[metric],color=['#8c8f94','#346e9d','#197c68','#c18b3b']);ax.set_xticks(np.arange(len(g)),g.model,rotation=15,ha='right');ax.set_title(title);ax.set_ylabel('Lower is better')
 fig.tight_layout();fig.savefig(dest/'model_comparison.png',dpi=155);plt.close(fig)
 q=d[d.eligible].sort_values(['season','team']);lines=['# Team-by-team prediction comparisons','Only cases with at least10 tracked later hub-absent games enter this evaluation. Connection errors compare normalized directed edge shares. Entropy errors are absolute differences in normalized outgoing conditional entropy. Historical rows without an earlier saved season retain the initial prediction.','|Season|Team|Hub|Early present|Later absent|Initial connection error|Final connection error|Final entropy error|','|---|---|---|---:|---:|---:|---:|---:|']
 for z in q.itertuples():lines.append(f'|{z.season}|{z.team}|{z.hub_name}|{z.first20_hub_present_games}|{z.later_hub_absent_games}|{z.edge_current:.4f}|{z.edge_learned:.4f}|{z.entropy_error_learned:.4f}|')
 (dest/'TEAM_BY_TEAM.md').write_text('\n\n'.join(lines[:2])+'\n\n'+'\n'.join(lines[2:]))
 # Player-level minute and passing allocations, plus learned historical multipliers.
 ledger=pd.read_csv(data/'split_role_hub_redistribution/minutes_and_passing_role_weights.csv');changes=pd.read_csv(pred/'predicted_player_role_changes.csv');allocation=ledger.merge(changes,on=['season','team','player_id'],validate='one_to_one');allocation.to_csv(root/'replacement_roles/all_player_minutes_and_passing_roles.csv',index=False);shutil.copy2(pred/'learned_coefficients.csv',root/'replacement_roles/historical_model_coefficients.csv');shutil.copy2(pred/'predicted_player_role_changes.csv',root/'replacement_roles/historical_player_role_changes.csv')
 # Existing network images are exact displays of these unchanged predicted matrices.
 network=root/'networks';old=pd.DataFrame([{k:v for k,v in record.items() if k!='source_sha256'} for record in json.loads((network/'plot_provenance.json').read_text())]);old=old.rename(columns={'eligible':'legacy_primary_eligible'});old=old.drop(columns=['edge_current','edge_learned','later_hub_absent_games'],errors='ignore');info=old.merge(d[['season','team','eligible','edge_current','edge_learned','later_hub_absent_games']],on=['season','team'],validate='one_to_one');info.to_csv(network/'all_team_network_summary.csv',index=False)
 cards=[];esc=html.escape
 for z in info.sort_values(['season','team']).itertuples():
  note=f'{z.later_hub_absent_games} later hub-absent games; '+('included in 10+ evaluation' if z.eligible else 'illustration outside 10+ evaluation');cards.append(f'<article data-season="{z.season}" data-team="{z.team}" data-eligible="{str(z.eligible).lower()}"><h2>{z.season} {z.team} | {esc(z.hub_name)}</h2><p>{esc(note)}</p><a href="{z.image}"><img loading="lazy" src="{z.image}" alt="{z.season} {z.team}: original, predicted, actual"></a></article>')
 seasons=sorted(info.season.unique());teams=sorted(info.team.unique());page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Final passing-hub networks</title><style>body{font:16px/1.5 system-ui;color:#183441;background:#f2f5f7;margin:24px auto;max-width:1500px;padding:0 20px}article{background:white;border:1px solid #d6e0e4;border-radius:10px;margin:24px 0;padding:18px}h2{font-size:20px}img{display:block;width:100%;height:auto}select{font:inherit;padding:7px;margin:0 16px 0 4px}a{color:#176b85}[hidden]{display:none!important}.controls{position:sticky;top:0;padding:12px;background:#f2f5f7}</style><h1>Final: previous-season-only passing-hub model</h1><p>Left: original early hub-present games. Middle: previous-season-only prediction, excluding target-franchise historical training. Right: actual later hub-absent games.</p><p>180 graph sets are available. The default view shows only the 100 team-seasons with10+ tracked later absences;85 have historical training. The first saved season retains its initial prediction. Missing actual networks are labelled unavailable.</p><p><a href="all_180_team_networks.pdf">All180 graph PDF</a> · <a href="all_team_network_summary.csv">Graph data</a> · <a href="../README.md">Package guide</a></p><div class="controls"><label>Season<select id="season"><option value="">All seasons</option>'''+''.join(f'<option>{s}</option>' for s in seasons)+'''</select></label><label>Team<select id="team"><option value="">All teams</option>'''+''.join(f'<option>{t}</option>' for t in teams)+'''</select></label><label><input id="qualified" type="checkbox" checked> Only10+ later absences</label> <span id="count"></span></div>'''+''.join(cards)+'''<script>const s=document.getElementById('season'),t=document.getElementById('team'),q=document.getElementById('qualified'),cards=[...document.querySelectorAll('article')];function filter(){let n=0;for(const c of cards){c.hidden=!!((s.value&&s.value!==c.dataset.season)||(t.value&&t.value!==c.dataset.team)||(q.checked&&c.dataset.eligible!=='true'));if(!c.hidden)n++;}document.getElementById('count').textContent=n+' graphs';}for(const el of [s,t,q])el.addEventListener('change',filter);filter();</script></html>''';(network/'index.html').write_text(page)
 for season,g in info.groupby('season'):
  folder=network/season
  def md(rows,title):
   text=[f'# {title}','Panels: original early hub present; final previous-season-only prediction; actual later hub absent. Open an image for full resolution. Node sizes use each panel\'s own passing involvement.']
   for z in rows.itertuples():text.append(f'## {z.team} | {z.hub_name}\n\n{z.later_hub_absent_games} later absent games.\n\n![{z.team} three networks]({z.team}_three_networks.png)\n\n[Original matrix](../../data/nba_passing_output/all_season_hub_redistribution/{season}/{z.team}/original_evaluation.csv) | [Predicted matrix](../../prediction_model/{season}/{z.team}/predicted_evaluation.csv) | [Actual matrix](../../data/nba_passing_output/all_season_hub_redistribution/{season}/{z.team}/actual_evaluation.csv)')
   return '\n\n'.join(text)
  # From networks/<season>, reach package root with ../.. .
  (folder/'README.md').write_text(md(g[g.eligible].sort_values('team'),f'{season}: {int(g.eligible.sum())} teams with10+ later absences')+'\n\n[All30 team illustrations](all_teams.md) | [Season PDF](../'+season+'_all_30_teams.pdf)')
  (folder/'all_teams.md').write_text(md(g.sort_values('team'),season+': all30 team illustrations; evaluation includes only10+ later absences'))
 (network/'README.md').write_text('# Network graphs\n\nDefault galleries include only10+ later hub-absent-game comparisons. All180 illustrations and seven PDFs remain available.\n\n'+'\n'.join(f'- [{s} qualifying teams]({s}/README.md) | [All30]({s}/all_teams.md) | [PDF]({s}_all_30_teams.pdf)' for s in seasons)+'\n\n[Complete180-page PDF](all_180_team_networks.pdf) | [Local filterable HTML gallery](index.html)\n')
 print('Built final evaluation summaries, role tables and galleries:',len(info),'graphs;',int(info.eligible.sum()),'qualifying')

if __name__=='__main__':main()
